import{_ as s,o as t,c as n,ag as e}from"./chunks/framework.CoyAznnK.js";const u=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1778218878000}'),i={name:"guide/index.md"};function l(r,a,p,o,d,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><h2 id="什么是-aui-kit" tabindex="-1">什么是 AUI Kit？ <a class="header-anchor" href="#什么是-aui-kit" aria-label="Permalink to &quot;什么是 AUI Kit？&quot;">​</a></h2><p><strong>AUI Kit</strong>（AI-optimized Universal UI Kit）是一个专为 AI 编程工具设计的跨框架、跨端 UI 组件体系。</p><blockquote><p>开发者安装，AI 直接写出多平台一致的前端界面——无论你用 Vue 还是 React。</p></blockquote><h2 id="核心价值" tabindex="-1">核心价值 <a class="header-anchor" href="#核心价值" aria-label="Permalink to &quot;核心价值&quot;">​</a></h2><h3 id="🤖-ai-first" tabindex="-1">🤖 AI First <a class="header-anchor" href="#🤖-ai-first" aria-label="Permalink to &quot;🤖 AI First&quot;">​</a></h3><p>AUI Kit 从设计之初就考虑了 AI 编程工具的需求：</p><ul><li><strong>强约束</strong>：禁止手写 CSS，所有样式通过 Tailwind 类 + 设计令牌实现</li><li><strong>强类型</strong>：所有 Props 由 <code>@aui/core</code> 统一导出 TypeScript 接口，零 any</li><li><strong>强示例</strong>：每个组件源码头部附带 JSDoc + React/Vue 双框架示例</li></ul><h3 id="🎯-统一接口-方言输出" tabindex="-1">🎯 统一接口，方言输出 <a class="header-anchor" href="#🎯-统一接口-方言输出" aria-label="Permalink to &quot;🎯 统一接口，方言输出&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              AUI Kit 组件体系                     │</span></span>
<span class="line"><span>│                                                 │</span></span>
<span class="line"><span>│   组件名、Props、插槽语义、事件回调完全一致        │</span></span>
<span class="line"><span>│                                                 │</span></span>
<span class="line"><span>│   ┌──────────┐         ┌──────────┐             │</span></span>
<span class="line"><span>│   │ @aui/react│  ←AI→  │  @aui/vue │             │</span></span>
<span class="line"><span>│   │  React 18 │        │  Vue 3.4  │             │</span></span>
<span class="line"><span>│   │ + Tailwind│        │ + Tailwind│             │</span></span>
<span class="line"><span>│   └──────────┘         └──────────┘             │</span></span>
<span class="line"><span>│                                                 │</span></span>
<span class="line"><span>│   React 代码 ←同一套组件描述→ Vue 代码            │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="📱-跨端自适应" tabindex="-1">📱 跨端自适应 <a class="header-anchor" href="#📱-跨端自适应" aria-label="Permalink to &quot;📱 跨端自适应&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;Page platform=&quot;mobile&quot;&gt;</span></span>
<span class="line"><span>  &lt;Table ... /&gt;    → 自动转为 &lt;CardList ... /&gt;</span></span>
<span class="line"><span>  &lt;Modal ... /&gt;   → 自动转为 &lt;BottomSheet ... /&gt;</span></span>
<span class="line"><span>&lt;/Page&gt;</span></span></code></pre></div><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@aui/core          共享类型定义、设计令牌、跨端规则</span></span>
<span class="line"><span>    ├── @aui/react    React 18 实现，基于 Tailwind CSS</span></span>
<span class="line"><span>    └── @aui/vue      Vue 3 实现，基于 Tailwind CSS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@aui/cli           项目初始化，AI 规则注入</span></span>
<span class="line"><span>@aui/mcp           MCP Server，给 Claude/Cursor 提供组件查询</span></span></code></pre></div><h2 id="与传统组件库的区别" tabindex="-1">与传统组件库的区别 <a class="header-anchor" href="#与传统组件库的区别" aria-label="Permalink to &quot;与传统组件库的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Ant Design / Element Plus</th><th>AUI Kit</th></tr></thead><tbody><tr><td>设计目标</td><td>人类开发者使用</td><td>AI + 人类开发者</td></tr><tr><td>样式方案</td><td>Less/SCSS 内置样式</td><td>Tailwind CSS（AI 可枚举）</td></tr><tr><td>组件 API</td><td>各框架独立设计</td><td>双框架统一</td></tr><tr><td>AI 友好度</td><td>一般</td><td>专为 AI 设计</td></tr><tr><td>移动端适配</td><td>需手动切换组件</td><td>自动适配</td></tr></tbody></table><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>✅ <strong>AI 编程场景</strong>：用 Cursor、Copilot、Windsurf、v0 等工具生成前端代码 ✅ <strong>多框架项目</strong>：同时维护 React 和 Vue 两个前端的项目 ✅ <strong>快速原型</strong>：需要快速出 UI 原型的场景 ✅ <strong>设计系统</strong>：构建企业级设计系统的基础层</p><h2 id="组件清单-40" tabindex="-1">组件清单（40+） <a class="header-anchor" href="#组件清单-40" aria-label="Permalink to &quot;组件清单（40+）&quot;">​</a></h2><ul><li><strong>布局与导航</strong>：Page、Grid、Flex、Spacer、Tabs、Drawer、Menu</li><li><strong>数据展示</strong>：Table、CardList、Descriptions、Tag、Badge、Avatar、Progress、Statistic</li><li><strong>表单与输入</strong>：Form、Form.Item、Input、TextArea、Select、DatePicker、Switch、Radio、Checkbox、Rate、Upload</li><li><strong>反馈与交互</strong>：Button、Modal、Toast、Popconfirm、Empty、Skeleton、Spin</li><li><strong>移动端增强</strong>：BottomSheet、Swiper、PullRefresh、IndexBar</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/installation">安装指南 →</a></li><li><a href="/guide/quick-start">快速上手 →</a></li><li><a href="/guide/ai-integration">AI 集成 →</a></li></ul>`,22)])])}const g=s(i,[["render",l]]);export{u as __pageData,g as default};
